-- Listage de la structure de table cabinetdentaire. observations_dent
CREATE TABLE IF NOT EXISTS `observations_dent` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `num_dent` varchar(2) COLLATE utf8mb3_unicode_ci NOT NULL,
  `texte` text COLLATE utf8mb3_unicode_ci NOT NULL,
  `medecin_id` int DEFAULT NULL,
  `cabinet_id` int DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `observations_dent_medecin_id_foreign` (`medecin_id`),
  KEY `observations_dent_patient_id_num_dent_index` (`patient_id`,`num_dent`),
  CONSTRAINT `observations_dent_medecin_id_foreign` FOREIGN KEY (`medecin_id`) REFERENCES `medecins` (`idMedecin`) ON DELETE SET NULL,
  CONSTRAINT `observations_dent_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`ID`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

-- Listage des données de la table cabinetdentaire.observations_dent : ~0 rows (environ)

-- Listage de la structure de table cabinetdentaire. ordonnanceref
CREATE TABLE IF NOT EXISTS `ordonnanceref` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `refOrd` varchar(45) NOT NULL DEFAULT 'NR',
  `Annee` int unsigned NOT NULL DEFAULT '0',
  `numordre` int unsigned NOT NULL DEFAULT '0',
  `fkidpatient` int unsigned NOT NULL DEFAULT '0',
  `fkidprescripteur` int unsigned NOT NULL DEFAULT '1',
  `dtPrescript` datetime DEFAULT NULL,
  `fkidCabinet` int unsigned NOT NULL DEFAULT '1',
  `TypeOrdonnance` varchar(145) NOT NULL DEFAULT 'Ordonnances',
  `statutSoin` varchar(20) NOT NULL DEFAULT 'en_attente',
  PRIMARY KEY (`id`),
  KEY `Index_2` (`refOrd`),
  KEY `Index_3` (`Annee`),
  KEY `Index_4` (`fkidpatient`),
  KEY `Index_5` (`fkidprescripteur`),
  KEY `Index_6` (`dtPrescript`),
  KEY `Index_7` (`TypeOrdonnance`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=latin1;

