-- Listage de la structure de table cabinetdentaire. plan_traitement_dentaire
CREATE TABLE IF NOT EXISTS `plan_traitement_dentaire` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `num_dent` varchar(2) COLLATE utf8mb3_unicode_ci NOT NULL,
  `acte_id` int NOT NULL,
  `acte_libelle` varchar(245) COLLATE utf8mb3_unicode_ci NOT NULL,
  `medecin_id` int DEFAULT NULL,
  `statut` enum('planifie','en_cours','termine') COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'planifie',
  `prix_ref` decimal(10,2) DEFAULT NULL,
  `cabinet_id` int DEFAULT NULL,
  `detail_facture_id` int DEFAULT NULL,
  `facture_id` int DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `notes` text COLLATE utf8mb3_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `plan_traitement_dentaire_acte_id_foreign` (`acte_id`),
  KEY `plan_traitement_dentaire_medecin_id_foreign` (`medecin_id`),
  KEY `plan_traitement_dentaire_detail_facture_id_foreign` (`detail_facture_id`),
  KEY `plan_traitement_dentaire_facture_id_foreign` (`facture_id`),
  KEY `plan_traitement_dentaire_patient_id_num_dent_index` (`patient_id`,`num_dent`),
  KEY `plan_traitement_dentaire_patient_id_statut_index` (`patient_id`,`statut`),
  CONSTRAINT `plan_traitement_dentaire_acte_id_foreign` FOREIGN KEY (`acte_id`) REFERENCES `actes` (`ID`),
  CONSTRAINT `plan_traitement_dentaire_detail_facture_id_foreign` FOREIGN KEY (`detail_facture_id`) REFERENCES `detailfacturepatient` (`idDetfacture`) ON DELETE SET NULL,
  CONSTRAINT `plan_traitement_dentaire_facture_id_foreign` FOREIGN KEY (`facture_id`) REFERENCES `facture` (`Idfacture`) ON DELETE SET NULL,
  CONSTRAINT `plan_traitement_dentaire_medecin_id_foreign` FOREIGN KEY (`medecin_id`) REFERENCES `medecins` (`idMedecin`),
  CONSTRAINT `plan_traitement_dentaire_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`ID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

